    "darboux": "Darboux sums",
    "prompt_darboux": "Split the interval into equal parts and compare the lower sum (from infima) and the upper sum (from suprema) with the integral. Predict both sums, and only then show them. What happens when you refine the partition? Why is the supremum of sin x on one part not a value at an endpoint?",
