    "taylor_bound_help": "Predict first: how does the error |f(x) − Tₙ(x)| change when you raise the degree? Then show the Lagrange error bound: an upper limit for the error under the stated assumption about the derivative.",
    "taylor_hidden": "hidden",
    "taylor_readout_polynomial": "Polynomial Tₙ(x)",
    "taylor_readout_function": "Function f(x)",
    "taylor_readout_signed_error": "Error f(x) − Tₙ(x)",
