    "taylor_readout_series": "Series as n → ∞",
    "taylor_bound_unavailable": "not shown (see the note)",
    "taylor_hypothesis_exp": "|f^(n+1)| ≤ M = max(e^c, e^x) between c and x, because e^t is increasing; the bound is M·|x − c|^(n+1)/(n+1)!",
    "taylor_hypothesis_sine": "|f^(n+1)| ≤ M = 1, because every derivative of sin x is ±sin x or ±cos x; the bound is |x − c|^(n+1)/(n+1)!",
    "taylor_hypothesis_geometric": "|f^(n+1)| ≤ M = (n+1)!/(1 − max(c, x))^(n+2) between c and x, because f^(n+1) is increasing on x < 1; the bound is |x − c|^(n+1)/(1 − max(c, x))^(n+2)",
    "taylor_hypothesis_flat": "no bound: the derivatives at c = 0 are all 0 and give no limit for the remainder",
    "taylor_series_everywhere": "The series converges to f for every x.",
    "taylor_series_geometric_inside": "The series converges to f for x between {value0} and {value1} (|x − c| < 1 − c); x is inside.",
    "taylor_series_geometric_outside": "The series converges only for x between {value0} and {value1} (|x − c| < 1 − c); x is outside, where it does not converge.",
    "taylor_series_flat": "Every term of the series is 0, so the series converges, but to 0 and not to f (for x > 0, f(x) > 0).",
    "taylor_note": "Tₙ is a finite polynomial and always exists; whether the infinite Taylor series converges, and to what, is a separate question. The error is computed directly as f(x) − Tₙ(x); values below 10⁻¹² are shown as 0 because of rounding.",
    "taylor_status_hidden": "The error bound is hidden: Tₙ and the error are shown but the bound is not. Predict how the error changes with the degree, then show it.",
    "taylor_status_revealed": "The Lagrange remainder bound is shown, with its assumption about |f^(n+1)| between c and x; the actual error does not exceed the bound.",
    "taylor_status_inside": "The point x is inside the convergence interval: there Tₙ(x) approaches f(x) as n grows.",
    "taylor_status_outside": "The point x is outside the convergence interval: the series does not converge there and a higher degree does not reduce the error.",
    "taylor_status_no_bound": "No error bound is shown for this function: all derivatives at c = 0 are 0, yet f(x) > 0 for x > 0, so a limit for |f^(n+1)| would have to come from derivatives elsewhere, which this demonstration does not model.",
    "taylor_status_bound_not_sharp": "The Lagrange bound is valid here but not sharp: it can stay large or even grow with n while the actual error inside the convergence interval tends to 0.",
    "taylor_status_flat": "Every coefficient of the series at c = 0 is 0, so Tₙ = 0 at every degree. For x > 0, f(x) > 0, so Tₙ does not approximate f even though f is smooth: the series converges to 0, not to f.",
    "taylor_board_parameters": "c = {value0}, n = {value1}, x = {value2}",
