    "sequence_note": "A term on the edge of the band, where |aₙ − L| = ε, is outside the band: the inequality in the definition is strict. The certificate comes from the formula of the sequence and holds for every n ≥ N, also for terms you do not see; a finite window of shown terms does not prove convergence.",
    "sequence_status_hidden": "The certificate is hidden. Choose N and predict whether |aₙ − L| < ε for every n ≥ N; only then press Show certificate.",
    "sequence_status_certified": "N = {value0} works: for every n ≥ {value0}, |aₙ − L| = 1/n ≤ 1/{value0} < ε, because N · ε = {value1} > 1. The least working N is {value2}.",
    "sequence_status_threshold_fails": "N = {value0} does not work: at n = {value0}, |aₙ − L| = 1/{value0} ≥ ε, because N · ε = {value1} ≤ 1. The least working N is {value2}.",
    "sequence_status_not_the_limit": "L = {value0} is not the limit of this sequence (the limit is {value1}), so there is no certificate: for a small enough ε the terms do not stay in the band around L from any N on.",
    "sequence_status_oscillating": "No certificate: the values 1 and −1 recur beyond every N, and the farther of them is at distance 1 + |L| = {value0} ≥ ε = {value1} from L, so no N works. A finite window of terms does not change that.",
    "sequence_status_epsilon_satisfied": "For this ε every term lies in the band (1 + |L| = {value0} < ε = {value1}), but that is a single ε: convergence requires an N for every ε > 0. Lower ε to {value0} or less and see what happens.",
    "sequence_status_divergent": "No certificate: aₙ = n exceeds L + ε for every n ≥ {value0}, the terms leave the band for good and no N works.",
    "sequence_status_beyond_terms": "N = {value0} is beyond the shown terms (n ≤ {value1}). The conclusion comes from the formula of the sequence for all n ≥ N, not from the shown terms.",
    "sequence_status_n_min_beyond_terms": "The least working N = {value0} is beyond the shown terms (n ≤ {value1}); Next step or Play reveals them up to n = {value2}.",
    "sequence_status_n_min_beyond_all": "The least working N = {value0} is beyond all {value1} terms the app draws; the claim holds by the formula, also for terms you do not see.",
