    "fixed_point_bound_help": "First predict where the next iterate lands and whether the iteration converges. Then show the error bound: the contraction theorem gives it only if T maps a closed interval into itself and |T′| ≤ q < 1.",
    "fixed_point_hidden": "hidden",
