    "fixed_point_no_bound": "no bound (not a contraction)",
    "fixed_point_note": "The error bounds are guaranteed only if T is a contraction on a closed interval that it maps into itself. A stop at the threshold says that the bound is below the threshold, not that xₖ is an exact fixed point; equal rounded iterates do not prove an exact fixed point.",
    "fixed_point_status_bound_hidden": "The error bound is hidden. Predict the next iterate and whether the iteration converges; only then press Show error bound.",
    "fixed_point_hyp_interval": "The interval [{value0}, {value1}] is closed and bounded, hence complete.",
    "fixed_point_hyp_selfmap_increasing": "T is increasing, so T([0, 2]) = [1/2, 3/2], which lies in [0, 2].",
    "fixed_point_hyp_selfmap_cosine": "cos is decreasing on [0, 1], so cos([0, 1]) = [cos 1, 1], which lies in [0, 1].",
    "fixed_point_hyp_selfmap_reflection": "T swaps the endpoints of [0, 1], so T([0, 1]) = [0, 1].",
    "fixed_point_hyp_contraction_constant": "|T′(x)| = 1/2 for every x, so by the mean value theorem |T(x) − T(y)| ≤ q |x − y| with q = 1/2 < 1.",
    "fixed_point_hyp_contraction_sine": "|T′(x)| = sin x ≤ sin 1 on [0, 1], so by the mean value theorem |T(x) − T(y)| ≤ q |x − y| with q = sin 1 ≈ {value0} < 1.",
    "fixed_point_status_bound_a_priori": "A priori: |xₖ − x*| ≤ q^k/(1 − q) · |x₁ − x₀| = {value0}.",
    "fixed_point_status_bound_a_posteriori": "A posteriori: |xₖ − x*| ≤ q/(1 − q) · |xₖ − xₖ₋₁| = {value0}.",
    "fixed_point_status_bound_pending": "The a posteriori bound needs at least one step: press Next step.",
    "fixed_point_status_no_bound": "For T(x) = 1 − x we have |T′| = 1, so there is no q < 1 and the contraction theorem gives no bound. That does not mean the iteration diverges: only the conclusion of the theorem is missing.",
    "fixed_point_status_cycle": "Two-cycle: the iterates alternate between {value0} and {value1} and do not settle. The cause is T(T(x)) = x. Since |T′| = 1, T is not a contraction, so the theorem does not apply, which by itself does not prove divergence.",
    "fixed_point_status_threshold": "Stopped at step {value1}: the a posteriori bound is below the threshold {value0}. This says the error is below the threshold, not that xₖ is an exact fixed point.",
    "fixed_point_status_limit": "Stopped: the limit of {value0} steps is reached. This is not a conclusion about convergence.",
