    "uniform_beyond_cap": "beyond {value0}",
    "uniform_note": "The pointwise N(x, ε) depends on the chosen point x. The shared N(ε) has to work for every point of the domain at once, so it is determined by the supremum error, computed from the formula and not from sampled values. N can exceed the largest index n you can select; the readout says so and does not shorten it. Changing the domain end r is a new comparison, not a continuation of the old one.",
    "uniform_status_hidden": "The supremum is hidden. Predict which point has the largest error and whether one n suits every point at once; only then press Show supremum.",
    "uniform_status_attained": "The supremum error is {value0} and it is attained at x = {value1}.",
    "uniform_status_not_attained": "The supremum error is {value0} and it is not attained: no point of the domain reaches it, but the error approaches it near x = {value1}.",
    "uniform_status_shared_n": "Shared N = {value0}: for every n ≥ {value0} the supremum is below ε = {value1}, so fₙ lies inside the band at all x at once.",
    "uniform_status_shared_n_boundary": "Shared N = {value0}: the supremum equals ε = {value1} but is not attained, so for every n ≥ {value0} every error is below ε and fₙ lies inside the band at all x at once.",
    "uniform_status_no_shared_n": "There is no shared N: the supremum is {value0} for every n, so no n has a supremum below ε = {value1}.",
    "uniform_status_shared_n_beyond": "The shared N = {value0} is beyond the largest index n = {value1} you can select; by the formula the statement holds for larger n too.",
    "uniform_status_covered": "At n = {value0} the supremum is below ε: the whole graph of fₙ lies inside the band.",
    "uniform_status_covered_boundary": "At n = {value0} every error is below ε (the supremum equals ε but is not attained): the whole graph of fₙ lies inside the band.",
    "uniform_status_not_covered": "At n = {value0} the supremum is not below ε: the whole graph of fₙ is not guaranteed to lie inside the band.",
