    "complex_roots_example_label": "Roots example",
    "complex_roots_example_help": "Choosing an example sets w and n and hides the roots, the n-gon and the test point. Editing the numbers keeps the display choice.",
    "complex_roots_example_two_i": "w = 2i, n = 3",
