    "complex_roots_fields_help": "The number w is on the 0.05 grid between −2 and 2, the degree n is an integer from 2 to 8. You can also drag w and the test point z; z appears after Show test point.",
    "complex_roots_actions_label": "Show the roots, the regular n-gon and the test point",
    "complex_roots_show_roots": "Show roots",
