    "complex_roots_reveal_help": "First predict where the solutions of z^n = w lie; then show the indexed roots, the regular n-gon through them, or the test point z, whose z^n you compare with w.",
    "complex_roots_readout_degree": "Degree n",
    "complex_roots_readout_radius": "Radius of the n-gon |w|^(1/n)",
    "complex_roots_readout_roots": "Roots of z^n = w",
    "complex_roots_readout_root": "Root {value0}",
    "complex_roots_root_value": "{value0}; |z| = {value1}, arg z = {value2}",
    "complex_roots_zero_value": "0, multiplicity {value0}",
    "complex_roots_readout_test": "Test point z",
    "complex_roots_readout_test_power": "Power z^n",
    "complex_roots_readout_test_gap": "Distance |z^n − w|",
    "complex_roots_note": "For w ≠ 0 the equation z^n = w has exactly n solutions (the fundamental theorem of algebra applied to z^n − w; the picture does not prove this); they lie at the vertices of a regular n-gon of radius |w|^(1/n). Root z_k has modulus |w|^(1/n) and argument (Arg w + 2πk)/n, with the principal argument Arg w in (−π, π]; root z₀ is the principal one. The labels of the roots jump when w crosses the negative real axis, though the set of roots stays the same. The roots sum to 0 and their product is (−1)^(n+1) w. Values are computed from the grid coordinates and rounded.",
    "complex_roots_status_predict": "The roots are hidden. Predict where the solutions of z^n = w lie; only then press Show roots.",
    "complex_roots_status_zero": "w = 0: the only solution is z = 0, counted n times (multiplicity n). There is no n-gon, because all n vertices coincide at 0; the argument of 0 is not defined.",
    "complex_roots_status_on_cut": "w is on the negative real axis, so arg w is exactly π. When w crosses the axis the labels of the roots move, though the set of roots stays the same.",
    "complex_roots_status_test_solves": "z^n = w up to rounding (difference below 10⁻⁹): the test point z is a root.",
    "complex_roots_status_test_fails": "z^n ≠ w: the test point z is not a root; the distance |z^n − w| is in the readouts.",
    "complex_roots_board_operands": "w = {value0}, n = {value1}",
