    // Computational geometry: family and Batch 1 Demonstration titles and prompts.
    "computational_geometry": "Computational geometry",
    "compgeo_orientation_title": "Orientation of three points",
    "prompt_compgeo_orientation_turn": "Move the point r and watch when the turn p, q, r changes from left to right. What does the sign of the determinant expression say, and where does r lie when the value is 0?",
    "prompt_compgeo_orientation_collinear": "Place r on the line through p and q. Why is the value exactly 0 then, and how does that separate a left turn from a right turn?",
    "compgeo_polygon_area_title": "Polygon area",
    "prompt_compgeo_polygon_area_shoelace": "Move the vertices and watch the signed area from the shoelace formula. What happens to the sign if you reverse the order of the vertices?",
    "prompt_compgeo_polygon_area_pick": "Count the interior and boundary lattice points and check Pick's theorem. When does the theorem hold, and what happens for a self-intersecting polygon?",
    "compgeo_convex_hull_title": "Convex hull",
    "prompt_compgeo_convex_hull_trace": "Press Next step and predict which point the algorithm keeps or discards next. Which turn makes a point drop out of the hull?",
    "prompt_compgeo_convex_hull_degenerate": "Put several points on one line or duplicate them. How does the hull change, and what do the different algorithms do in degenerate cases?",
    "compgeo_ear_clipping_title": "Ear-clipping triangulation",
    "prompt_compgeo_ear_clipping_ears": "Press Next step and predict which vertex is an ear. When is a vertex an ear, and why can it be clipped off?",
    "prompt_compgeo_ear_clipping_reflex": "Move a vertex so that it becomes reflex. What happens to the ears, and why does every simple polygon have at least two ears?",
    "compgeo_point_set_triangulation_title": "Triangulating a point set",
    "prompt_compgeo_point_set_triangulation_flip": "Flip the diagonal in the quadrilateral of two adjacent triangles. When is a flip possible, and how do the smallest angle and the number of triangles change?",
    "prompt_compgeo_point_set_triangulation_count": "Add or move points and count the triangles and edges. Why are both numbers always the same for a given point set, whichever triangulation you choose?",
    "compgeo_delaunay_title": "Delaunay triangulation",
    "prompt_compgeo_delaunay_illegal": "Press Next step and find an illegal diagonal. Why does the fourth point lie inside the circumcircle of the triangle, and what does flipping the diagonal do?",
    "prompt_compgeo_delaunay_cocircular": "Place four points on a common circle. Why are both diagonals legal, and why is the Delaunay triangulation not unique?",
    "compgeo_voronoi_title": "Voronoi diagram",
    "prompt_compgeo_voronoi_cell": "Choose a site and show the bisectors one by one. How does the cell of the site arise from them, and why is the intersection of the half-planes always convex?",
    "prompt_compgeo_voronoi_query": "Move the query point and see which cell it lies in. Why is the nearest site always the site of that cell, and what does the duality overlay show?",
    "compgeo_voronoi_degenerate_title": "Degenerate sites",
    "prompt_compgeo_voronoi_degenerate_cocircular": "Place four sites on a common circle. How many Voronoi vertices do you get, what is their degree, and why are both diagonals legal?",
    "prompt_compgeo_voronoi_degenerate_collinear": "Place all the sites on one line. Why are there no Voronoi vertices, why are the cells strips, and why is there no Delaunay triangulation?",
    "compgeo_interval_sweep_title": "Interval sweep",
    "prompt_compgeo_interval_sweep_events": "Press Next step and watch the sweep line. Which events change the status, and when does it grow or shrink?",
    "prompt_compgeo_interval_sweep_depth": "Move an endpoint of an interval. How does the largest number of simultaneously open intervals change, and where does it occur?",
    "compgeo_segment_intersections_title": "Segment intersections",
    "prompt_compgeo_segment_intersections_neighbours": "Press Next step and watch the status of the sweep line. Which neighbouring segments must be tested when a segment enters or leaves?",
    "prompt_compgeo_segment_intersections_swap": "Find the event where two segments swap places in the status. Why are they neighbours just before the intersection point, and what happens to the new neighbours?",
    "compgeo_monotone_partition_title": "Monotone partition",
    "prompt_compgeo_monotone_partition_vertex_types": "Press Next step and watch the vertex types. Which vertices are split and merge vertices, and why must each be joined by a diagonal?",
    "prompt_compgeo_monotone_partition_diagonals": "Move a vertex so that a split vertex disappears. How does the number of diagonals change, and are the pieces really monotone?",
    "compgeo_monotone_triangulation_title": "Monotone triangulation",
    "prompt_compgeo_monotone_triangulation_stack": "Press Next step and watch the stack. When do we cut off triangles with diagonals, and when do we just push the vertex?",
    "prompt_compgeo_monotone_triangulation_chains": "Find a vertex on the other chain than the top of the stack. Why can it then be joined to every vertex in the stack?",
    "compgeo_fortune_title": "Fortune's algorithm",
    "prompt_compgeo_fortune_false_alarm": "Press Next step and find the dashed, cancelled circle. Which site lies inside it, and why does the arc on the beach line then not disappear?",
    "prompt_compgeo_fortune_delaunay_dual": "Press Next step to the end and compare the finished Voronoi diagram with the Delaunay triangulation of the same sites. Which triangle belongs to a vertex of the diagram, and why does its circumcircle contain no other site?",
    "compgeo_point_in_polygon_title": "Point in polygon",
    "prompt_compgeo_point_in_polygon_ray": "Move the point q and watch the ray cross the polygon's edges. When does the number of crossings change, and what does it tell you about the position of q?",
    "prompt_compgeo_point_in_polygon_self_intersecting": "Load the pentagram and move the point q into its centre. Why do the even-odd and nonzero rules give different answers there?",
    "compgeo_hull_robustness_title": "Degenerate cases and robustness",
    "prompt_compgeo_hull_robustness_rule": "Press Next step under both pop rules. What happens to a collinear point on a hull edge?",
    "prompt_compgeo_hull_robustness_kettner": "Switch to the sign map and compare the inexact and the exact map. In which cells do the signs differ?",
